package com.example.sleepplayer;

import android.graphics.Color;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.recyclerview.widget.RecyclerView;

import com.bumptech.glide.Glide;
import com.bumptech.glide.load.resource.drawable.DrawableTransitionOptions;

import java.util.ArrayList;
import java.util.List;

/**
 * RecyclerView-Adapter für die Track-Liste.
 *
 * Unterstützt:
 *  - Klick → Track abspielen
 *  - Longpress → Track als Normalisierungs-Referenz markieren
 *  - Badge-Anzeige für Referenz-Track (⭐) und normalisierte Tracks (Gain in dB)
 */
public class TrackAdapter extends RecyclerView.Adapter<TrackAdapter.TrackViewHolder> {

    private List<TrackSelector.TrackInfo> tracks = new ArrayList<>();
    private OnTrackClickListener listener;
    private OnTrackLongClickListener longClickListener;
    private NormalizationStore normStore;

    public interface OnTrackClickListener {
        void onTrackClick(TrackSelector.TrackInfo track);
    }

    public interface OnTrackLongClickListener {
        void onTrackLongClick(TrackSelector.TrackInfo track);
    }

    public void setOnTrackClickListener(OnTrackClickListener listener) {
        this.listener = listener;
    }

    public void setOnTrackLongClickListener(OnTrackLongClickListener listener) {
        this.longClickListener = listener;
    }

    public void setNormalizationStore(NormalizationStore store) {
        this.normStore = store;
    }

    public void setTracks(List<TrackSelector.TrackInfo> tracks) {
        this.tracks = tracks != null ? tracks : new ArrayList<>();
        notifyDataSetChanged();
    }

    @NonNull
    @Override
    public TrackViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(parent.getContext())
                .inflate(R.layout.item_track, parent, false);
        return new TrackViewHolder(view);
    }

    @Override
    public void onBindViewHolder(@NonNull TrackViewHolder holder, int position) {
        TrackSelector.TrackInfo track = tracks.get(position);
        holder.tvTitle.setText(track.title);
        holder.tvArtist.setText(track.artist);
        holder.tvDuration.setText(track.getFormattedDuration());

        // Normalisierungs-Badge anzeigen
        if (normStore != null) {
            String uri = track.uri.toString();
            String refUri = normStore.getReferenceTrackUri();
            if (uri.equals(refUri)) {
                holder.tvNormBadge.setVisibility(View.VISIBLE);
                holder.tvNormBadge.setText("⭐ Ref");
                holder.tvNormBadge.setTextColor(Color.parseColor("#FFD700"));
            } else if (normStore.hasSectionalGains(uri)) {
                // Sektionsweise normalisiert – zeige  + Track-Gain falls vorhanden
                float gain = normStore.getGain(uri);
                float gainDb = (float)(20.0 * Math.log10(gain));
                String label = Math.abs(gainDb) < 0.5f
                        ? " sek."
                        : String.format(" %+.1fdB", gainDb);
                holder.tvNormBadge.setVisibility(View.VISIBLE);
                holder.tvNormBadge.setText(label);
                holder.tvNormBadge.setTextColor(Color.parseColor("#29B6F6")); // hellblau
            } else if (normStore.hasGain(uri)) {
                // Nur Gesamt-Gain vorhanden
                float gain = normStore.getGain(uri);
                float gainDb = (float)(20.0 * Math.log10(gain));
                String label;
                if (Math.abs(gainDb) < 0.5f) {
                    label = "±0 dB";
                } else {
                    label = String.format("%+.1f dB", gainDb);
                }
                holder.tvNormBadge.setVisibility(View.VISIBLE);
                holder.tvNormBadge.setText(label);
                if (gainDb > 0.5f) {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#4CAF50"));
                } else if (gainDb < -0.5f) {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#FF5252"));
                } else {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#99FFFFFF"));
                }
            } else {
                holder.tvNormBadge.setVisibility(View.GONE);
            }
        } else {
            holder.tvNormBadge.setVisibility(View.GONE);
        }

        // Album-Art laden
        Glide.with(holder.itemView.getContext())
                .load(track.getAlbumArtUri())
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .transition(DrawableTransitionOptions.withCrossFade(150))
                .centerCrop()
                .into(holder.ivAlbumArt);

        holder.itemView.setOnClickListener(v -> {
            if (listener != null) {
                listener.onTrackClick(track);
            }
        });

        holder.itemView.setOnLongClickListener(v -> {
            if (longClickListener != null) {
                longClickListener.onTrackLongClick(track);
                return true;
            }
            return false;
        });
    }

    @Override
    public int getItemCount() {
        return tracks.size();
    }

    static class TrackViewHolder extends RecyclerView.ViewHolder {
        final ImageView ivAlbumArt;
        final TextView tvTitle;
        final TextView tvArtist;
        final TextView tvDuration;
        final TextView tvNormBadge;

        TrackViewHolder(@NonNull View itemView) {
            super(itemView);
            ivAlbumArt  = itemView.findViewById(R.id.ivItemAlbumArt);
            tvTitle     = itemView.findViewById(R.id.tvItemTitle);
            tvArtist    = itemView.findViewById(R.id.tvItemArtist);
            tvDuration  = itemView.findViewById(R.id.tvItemDuration);
            tvNormBadge = itemView.findViewById(R.id.tvItemNormBadge);
        }
    }
}

package com.example.sleepplayer;

import android.graphics.Color;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ImageView;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.recyclerview.widget.RecyclerView;

import com.bumptech.glide.Glide;
import com.bumptech.glide.load.resource.drawable.DrawableTransitionOptions;

import java.util.ArrayList;
import java.util.List;

/**
 * RecyclerView-Adapter für die Track-Liste.
 *
 * Unterstützt:
 *  - Klick → Track abspielen
 *  - Longpress → Track als Normalisierungs-Referenz markieren
 *  - Badge-Anzeige für Referenz-Track (⭐) und normalisierte Tracks (Gain in dB)
 */
public class TrackAdapter extends RecyclerView.Adapter<TrackAdapter.TrackViewHolder> {

    private List<TrackSelector.TrackInfo> tracks = new ArrayList<>();
    private OnTrackClickListener listener;
    private OnTrackLongClickListener longClickListener;
    private NormalizationStore normStore;

    public interface OnTrackClickListener {
        void onTrackClick(TrackSelector.TrackInfo track);
    }

    public interface OnTrackLongClickListener {
        void onTrackLongClick(TrackSelector.TrackInfo track);
    }

    public void setOnTrackClickListener(OnTrackClickListener listener) {
        this.listener = listener;
    }

    public void setOnTrackLongClickListener(OnTrackLongClickListener listener) {
        this.longClickListener = listener;
    }

    public void setNormalizationStore(NormalizationStore store) {
        this.normStore = store;
    }

    public void setTracks(List<TrackSelector.TrackInfo> tracks) {
        this.tracks = tracks != null ? tracks : new ArrayList<>();
        notifyDataSetChanged();
    }

    @NonNull
    @Override
    public TrackViewHolder onCreateViewHolder(@NonNull ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(parent.getContext())
                .inflate(R.layout.item_track, parent, false);
        return new TrackViewHolder(view);
    }

    @Override
    public void onBindViewHolder(@NonNull TrackViewHolder holder, int position) {
        TrackSelector.TrackInfo track = tracks.get(position);
        holder.tvTitle.setText(track.title);
        holder.tvArtist.setText(track.artist);
        holder.tvDuration.setText(track.getFormattedDuration());

        // Normalisierungs-Badge anzeigen
        if (normStore != null) {
            String uri = track.uri.toString();
            String refUri = normStore.getReferenceTrackUri();
            if (uri.equals(refUri)) {
                holder.tvNormBadge.setVisibility(View.VISIBLE);
                holder.tvNormBadge.setText("⭐ Ref");
                holder.tvNormBadge.setTextColor(Color.parseColor("#FFD700"));
            } else if (normStore.hasGain(uri)) {
                float gain = normStore.getGain(uri);
                float gainDb = (float)(20.0 * Math.log10(gain));
                String label;
                if (Math.abs(gainDb) < 0.5f) {
                    label = "±0 dB";
                } else {
                    label = String.format("%+.1f dB", gainDb);
                }
                holder.tvNormBadge.setVisibility(View.VISIBLE);
                holder.tvNormBadge.setText(label);
                if (gainDb > 0.5f) {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#4CAF50"));
                } else if (gainDb < -0.5f) {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#FF5252"));
                } else {
                    holder.tvNormBadge.setTextColor(Color.parseColor("#99FFFFFF"));
                }
            } else {
                holder.tvNormBadge.setVisibility(View.GONE);
            }
        } else {
            holder.tvNormBadge.setVisibility(View.GONE);
        }

        // Album-Art laden
        Glide.with(holder.itemView.getContext())
                .load(track.getAlbumArtUri())
                .placeholder(R.drawable.ic_album_placeholder)
                .error(R.drawable.ic_album_placeholder)
                .transition(DrawableTransitionOptions.withCrossFade(150))
                .centerCrop()
                .into(holder.ivAlbumArt);

        holder.itemView.setOnClickListener(v -> {
            if (listener != null) {
                listener.onTrackClick(track);
            }
        });

        holder.itemView.setOnLongClickListener(v -> {
            if (longClickListener != null) {
                longClickListener.onTrackLongClick(track);
                return true;
            }
            return false;
        });
    }

    @Override
    public int getItemCount() {
        return tracks.size();
    }

    static class TrackViewHolder extends RecyclerView.ViewHolder {
        final ImageView ivAlbumArt;
        final TextView tvTitle;
        final TextView tvArtist;
        final TextView tvDuration;
        final TextView tvNormBadge;

        TrackViewHolder(@NonNull View itemView) {
            super(itemView);
            ivAlbumArt  = itemView.findViewById(R.id.ivItemAlbumArt);
            tvTitle     = itemView.findViewById(R.id.tvItemTitle);
            tvArtist    = itemView.findViewById(R.id.tvItemArtist);
            tvDuration  = itemView.findViewById(R.id.tvItemDuration);
            tvNormBadge = itemView.findViewById(R.id.tvItemNormBadge);
        }
    }
}

package com.example.sleepplayer;

import android.content.Context;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.speech.tts.TextToSpeech;
import android.speech.tts.UtteranceProgressListener;
import android.util.Log;

import java.util.Calendar;
import java.util.Locale;

/**
 * Hilfklasse für Text-to-Speech-Ansagen (Sprachsynthese).
 *
 * Verwendet die im Gerät installierte TTS-Engine (keine externe Abhängigkeit).
 * Initialisierung ist asynchron – Ansagen werden gepuffert bis die Engine bereit ist.
 * Unterstützt einen "onDone"-Callback und Lautstärkenregelung.
 */
public class TtsHelper implements TextToSpeech.OnInitListener {

    private static final String TAG = "TtsHelper";
    private static final String UTTERANCE_ID = "sleep_player_tts";

    private TextToSpeech tts;
    private boolean ready = false;
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    /** Puffer für Ansagen, die vor der Initialisierung angefordert wurden. */
    private String pendingText = null;
    private float pendingVolume = 1.0f;
    private Runnable pendingOnDone = null;

    /** Aktuelle Lautstärke (0.0–1.0, entspricht MediaPlayer-Lautstärke). */
    private float currentVolume = 1.0f;

    /** Callback der nach Abschluss der Ansage auf dem Main-Thread ausgeführt wird. */
    private Runnable onDoneCallback = null;

    public TtsHelper(Context context) {
        tts = new TextToSpeech(context.getApplicationContext(), this);
    }

    // ===== TextToSpeech.OnInitListener =====

    @Override
    public void onInit(int status) {
        if (status == TextToSpeech.SUCCESS) {
            // Deutsch bevorzugen, Fallback auf Gerätesprache
            int result = tts.setLanguage(Locale.GERMAN);
            if (result == TextToSpeech.LANG_MISSING_DATA
                    || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                Log.w(TAG, "Deutsch nicht verfügbar – verwende Gerätesprache");
                tts.setLanguage(Locale.getDefault());
            }

            // Listener für Abschluss-Callback registrieren
            tts.setOnUtteranceProgressListener(new UtteranceProgressListener() {
                @Override
                public void onStart(String utteranceId) { /* nichts */ }

                @Override
                public void onDone(String utteranceId) {
                    fireOnDone();
                }

                @Override
                public void onError(String utteranceId) {
                    // Bei Fehler trotzdem Callback auslösen, damit Track startet
                    Log.w(TAG, "TTS-Fehler für Utterance: " + utteranceId);
                    fireOnDone();
                }
            });

            ready = true;
            Log.d(TAG, "TTS bereit");

            // Gepufferte Ansage nachholen
            if (pendingText != null) {
                speakNow(pendingText, pendingVolume, pendingOnDone);
                pendingText = null;
                pendingVolume = 1.0f;
                pendingOnDone = null;
            }
        } else {
            Log.e(TAG, "TTS-Initialisierung fehlgeschlagen (status=" + status + ")");
            // Trotzdem Callback auslösen damit Track startet
            fireOnDone();
        }
    }

    // ===== Öffentliche API =====

    /**
     * Liest die aktuelle Uhrzeit vor und ruft danach {@code onDone} auf dem Main-Thread auf.
     *
     * @param volume  Lautstärke (0.0–1.0), passend zur aktuellen Track-Lautstärke
     * @param onDone  Runnable, das nach Abschluss der Ansage ausgeführt wird (darf null sein)
     */
    public void speakCurrentTime(float volume, Runnable onDone) {
        Calendar cal = Calendar.getInstance();
        int hour   = cal.get(Calendar.HOUR_OF_DAY);
        int minute = cal.get(Calendar.MINUTE);

        String text;
        if (minute == 0) {
            text = "Es ist " + hour + " Uhr";
        } else {
            text = "Es ist " + hour + " Uhr " + minute;
        }

        Log.d(TAG, "Ansage (volume=" + volume + "): " + text);
        speak(text, volume, onDone);
    }

    /**
     * Liest die aktuelle Uhrzeit vor (ohne Callback, ohne spezielle Lautstärke).
     * Kompatibilitätsmethode – bevorzuge {@link #speakCurrentTime(float, Runnable)}.
     */
    public void speakCurrentTime() {
        speakCurrentTime(1.0f, null);
    }

    /**
     * Liest einen beliebigen Text vor.
     *
     * @param text    Zu sprechender Text
     * @param volume  Lautstärke (0.0–1.0)
     * @param onDone  Runnable nach Abschluss (darf null sein)
     */
    public void speak(String text, float volume, Runnable onDone) {
        if (text == null || text.isEmpty()) {
            if (onDone != null) mainHandler.post(onDone);
            return;
        }
        if (ready && tts != null) {
            speakNow(text, volume, onDone);
        } else {
            // TTS noch nicht initialisiert – puffern
            pendingText = text;
            pendingVolume = volume;
            pendingOnDone = onDone;
        }
    }

    /**
     * Liest einen beliebigen Text vor (ohne Callback).
     */
    public void speak(String text) {
        speak(text, 1.0f, null);
    }

    /**
     * Stoppt laufende Ansagen und gibt die TTS-Engine frei.
     * Muss in onDestroy() des Service aufgerufen werden.
     */
    public void release() {
        onDoneCallback = null;
        pendingOnDone = null;
        if (tts != null) {
            tts.stop();
            tts.shutdown();
            tts = null;
        }
        ready = false;
        pendingText = null;
        Log.d(TAG, "TTS freigegeben");
    }

    // ===== Intern =====

    private void speakNow(String text, float volume, Runnable onDone) {
        // Vorherigen Callback ersetzen (falls TTS unterbrochen wird)
        onDoneCallback = onDone;

        Bundle params = new Bundle();
        // KEY_PARAM_VOLUME: 0.0 (still) bis 1.0 (volle Stream-Lautstärke)
        // Wir clampen auf [0.05, 1.0] damit die Ansage immer hörbar bleibt
        float ttsVolume = Math.max(0.05f, Math.min(1.0f, volume));
        params.putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME, ttsVolume);

        // QUEUE_FLUSH: unterbricht ggf. laufende Ansage
        tts.speak(text, TextToSpeech.QUEUE_FLUSH, params, UTTERANCE_ID);
    }

    /** Löst den gespeicherten onDone-Callback auf dem Main-Thread aus (einmalig). */
    private void fireOnDone() {
        Runnable cb = onDoneCallback;
        onDoneCallback = null;
        if (cb != null) {
            mainHandler.post(cb);
        }
    }
}

package com.example.sleepplayer;

import android.content.Context;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.speech.tts.TextToSpeech;
import android.speech.tts.UtteranceProgressListener;
import android.util.Log;

import java.util.Calendar;
import java.util.Locale;

/**
 * Hilfklasse für Text-to-Speech-Ansagen (Sprachsynthese).
 *
 * Verwendet die im Gerät installierte TTS-Engine (keine externe Abhängigkeit).
 * Initialisierung ist asynchron – Ansagen werden gepuffert bis die Engine bereit ist.
 * Unterstützt einen "onDone"-Callback und Lautstärkenregelung.
 *
 * Sicherheits-Timeout: Falls der onDone-Callback der TTS-Engine nie feuert
 * (z.B. bei hängendem TTS-System), wird er nach TTS_TIMEOUT_MS automatisch
 * ausgelöst – so startet der Track trotzdem.
 */
public class TtsHelper implements TextToSpeech.OnInitListener {

    private static final String TAG = "TtsHelper";
    private static final String UTTERANCE_ID = "sleep_player_tts";

    /** Sicherheits-Timeout: falls onDone nach dieser Zeit nicht feuert → manuell auslösen. */
    private static final long TTS_TIMEOUT_MS = 8_000L;

    private TextToSpeech tts;
    private boolean ready = false;
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    /** Timeout-Runnable – wird bei jedem Speak neu geplant und bei onDone abgebrochen. */
    private final Runnable timeoutRunnable = () -> {
        Log.w(TAG, "TTS-Timeout: onDone hat nicht gefeuert – erzwinge Callback");
        fireOnDone();
    };

    /** Puffer für Ansagen, die vor der Initialisierung angefordert wurden. */
    private String pendingText = null;
    private float pendingVolume = 1.0f;
    private Runnable pendingOnDone = null;

    /** Aktuelle Lautstärke (0.0–1.0, entspricht MediaPlayer-Lautstärke). */
    private float currentVolume = 1.0f;

    /** Callback der nach Abschluss der Ansage auf dem Main-Thread ausgeführt wird. */
    private Runnable onDoneCallback = null;

    public TtsHelper(Context context) {
        tts = new TextToSpeech(context.getApplicationContext(), this);
    }

    // ===== TextToSpeech.OnInitListener =====

    @Override
    public void onInit(int status) {
        if (status == TextToSpeech.SUCCESS) {
            // Deutsch bevorzugen, Fallback auf Gerätesprache
            int result = tts.setLanguage(Locale.GERMAN);
            if (result == TextToSpeech.LANG_MISSING_DATA
                    || result == TextToSpeech.LANG_NOT_SUPPORTED) {
                Log.w(TAG, "Deutsch nicht verfügbar – verwende Gerätesprache");
                tts.setLanguage(Locale.getDefault());
            }

            // Listener für Abschluss-Callback registrieren
            tts.setOnUtteranceProgressListener(new UtteranceProgressListener() {
                @Override
                public void onStart(String utteranceId) {
                    Log.d(TAG, "TTS onStart: " + utteranceId);
                }

                @Override
                public void onDone(String utteranceId) {
                    Log.d(TAG, "TTS onDone: " + utteranceId);
                    fireOnDone();
                }

                @Override
                public void onError(String utteranceId) {
                    // Bei Fehler trotzdem Callback auslösen, damit Track startet
                    Log.w(TAG, "TTS-Fehler für Utterance: " + utteranceId);
                    fireOnDone();
                }
            });

            ready = true;
            Log.d(TAG, "TTS bereit | pendingText=" + (pendingText != null ? "'" + pendingText + "'" : "null"));

            // Gepufferte Ansage nachholen
            if (pendingText != null) {
                speakNow(pendingText, pendingVolume, pendingOnDone);
                pendingText = null;
                pendingVolume = 1.0f;
                pendingOnDone = null;
            }
        } else {
            Log.e(TAG, "TTS-Initialisierung fehlgeschlagen (status=" + status + ")");
            // Trotzdem Callback auslösen damit Track startet
            fireOnDone();
        }
    }

    // ===== Öffentliche API =====

    /**
     * Liest die aktuelle Uhrzeit vor und ruft danach {@code onDone} auf dem Main-Thread auf.
     *
     * @param volume  Lautstärke (0.0–1.0), passend zur aktuellen Track-Lautstärke
     * @param onDone  Runnable, das nach Abschluss der Ansage ausgeführt wird (darf null sein)
     */
    public void speakCurrentTime(float volume, Runnable onDone) {
        Calendar cal = Calendar.getInstance();
        int hour   = cal.get(Calendar.HOUR_OF_DAY);
        int minute = cal.get(Calendar.MINUTE);

        String text;
        if (minute == 0) {
            text = "Es ist " + hour + " Uhr";
        } else {
            text = "Es ist " + hour + " Uhr " + minute;
        }

        Log.d(TAG, "Ansage (volume=" + volume + "): " + text);
        speak(text, volume, onDone);
    }

    /**
     * Liest die aktuelle Uhrzeit vor (ohne Callback, ohne spezielle Lautstärke).
     * Kompatibilitätsmethode – bevorzuge {@link #speakCurrentTime(float, Runnable)}.
     */
    public void speakCurrentTime() {
        speakCurrentTime(1.0f, null);
    }

    /**
     * Liest einen beliebigen Text vor.
     *
     * @param text    Zu sprechender Text
     * @param volume  Lautstärke (0.0–1.0)
     * @param onDone  Runnable nach Abschluss (darf null sein)
     */
    public void speak(String text, float volume, Runnable onDone) {
        if (text == null || text.isEmpty()) {
            if (onDone != null) mainHandler.post(onDone);
            return;
        }
        if (ready && tts != null) {
            speakNow(text, volume, onDone);
        } else {
            // TTS noch nicht initialisiert – puffern
            pendingText = text;
            pendingVolume = volume;
            pendingOnDone = onDone;
        }
    }

    /**
     * Liest einen beliebigen Text vor (ohne Callback).
     */
    public void speak(String text) {
        speak(text, 1.0f, null);
    }

    /**
     * Stoppt laufende Ansagen und gibt die TTS-Engine frei.
     * Muss in onDestroy() des Service aufgerufen werden.
     */
    public void release() {
        mainHandler.removeCallbacks(timeoutRunnable);
        onDoneCallback = null;
        pendingOnDone = null;
        if (tts != null) {
            tts.stop();
            tts.shutdown();
            tts = null;
        }
        ready = false;
        pendingText = null;
        Log.d(TAG, "TTS freigegeben");
    }

    // ===== Intern =====

    private void speakNow(String text, float volume, Runnable onDone) {
        // Vorherigen Callback ersetzen (falls TTS unterbrochen wird)
        onDoneCallback = onDone;

        // Alten Timeout abbrechen und neuen starten
        mainHandler.removeCallbacks(timeoutRunnable);
        mainHandler.postDelayed(timeoutRunnable, TTS_TIMEOUT_MS);

        Bundle params = new Bundle();
        // KEY_PARAM_VOLUME: 0.0 (still) bis 1.0 (volle Stream-Lautstärke)
        // Wir clampen auf [0.05, 1.0] damit die Ansage immer hörbar bleibt
        float ttsVolume = Math.max(0.05f, Math.min(1.0f, volume));
        params.putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME, ttsVolume);

        Log.d(TAG, "speakNow: text='" + text + "' volume=" + ttsVolume
                + " timeout=" + TTS_TIMEOUT_MS + "ms");
        // QUEUE_FLUSH: unterbricht ggf. laufende Ansage
        tts.speak(text, TextToSpeech.QUEUE_FLUSH, params, UTTERANCE_ID);
    }

    /** Löst den gespeicherten onDone-Callback auf dem Main-Thread aus (einmalig). */
    private void fireOnDone() {
        mainHandler.removeCallbacks(timeoutRunnable); // Timeout abbrechen
        Runnable cb = onDoneCallback;
        onDoneCallback = null;
        if (cb != null) {
            Log.d(TAG, "fireOnDone: Callback wird ausgelöst");
            mainHandler.post(cb);
        }
    }
}
